class MCPModel(BaseModel):
    """Base class for all MCP protocol types."""

    model_config = ConfigDict(alias_generator=to_camel, populate_by_name=True)

class CacheableResult(Result):
    ttl_ms: Annotated[int, Field(ge=0)] = 0
    cache_scope: Literal["public", "private"] = "private"

class InputRequiredResult(Result):
    result_type: Literal["input_required"] = "input_required"
    input_requests: InputRequests | None = None
    request_state: str | None = None

    @model_validator(mode="after")
    def _require_one_field(self) -> Self:
        if not self.input_requests and self.request_state is None:
            raise ValueError("InputRequiredResult requires at least one ...")
        return self

def parse_client_request(
    method: str, version: str, params: Mapping[str, Any] | None,
    *, surface=CLIENT_REQUESTS, monolith=MONOLITH_REQUESTS,
) -> types.Request[Any, Any]:
    validate_client_request(method, version, params, surface=surface)
    return _monolith_row(monolith, method).model_validate(
        _body(method, params), by_name=False
    )

def serialize_server_result(
    method: str, version: str, data: Mapping[str, Any],
    *, surface=SERVER_RESULTS,
) -> dict[str, Any]:
    _check_known_version(version)
    adapter = _adapter(surface[(method, version)])
    return adapter.dump_python(
        adapter.validate_python(data, by_name=False),
        by_alias=True, mode="json", exclude_none=True
    )

def is_input_required(result: object) -> TypeGuard[types.InputRequiredResult | dict[str, Any]]:
    if isinstance(result, types.InputRequiredResult):
        return True
    return isinstance(result, Mapping) and cast(
        "Mapping[str, Any]", result
    ).get("resultType") == "input_required"

def is_version_at_least(version: str, minimum: str) -> bool:
    if minimum not in KNOWN_PROTOCOL_VERSIONS:
        raise ValueError(f"minimum must be a known protocol version, got {minimum!r}")
    if version not in KNOWN_PROTOCOL_VERSIONS:
        return False
    return KNOWN_PROTOCOL_VERSIONS.index(version) >= KNOWN_PROTOCOL_VERSIONS.index(minimum)
